    b = np.array(rhs, dtype=np.int64, copy=True) % p
    m, n = M.shape

    A = np.concatenate((M, b.reshape(-1, 1)), axis=1)
    rank = 0
    pivots = []
    for col in range(n):
        rows = np.nonzero(A[rank:, col] % p)[0]
        if len(rows) == 0:
            continue
        pr = rank + rows[0]
        if pr != rank:
            A[[rank, pr], :] = A[[pr, rank], :]
        inv = pow(int(A[rank, col]), p - 2, p)
        A[rank, :] = (A[rank, :] * inv) % p
        nz = np.where(A[:, col] != 0)[0]
        if len(nz):
            keep = nz != rank
            nz = nz[keep]
            if len(nz):
                A[nz, :] = (A[nz, :] - (A[nz, col][:, None] * A[rank, :])) % p
        pivots.append(col)
        rank += 1
